SELECT  FROM APIGRAB_DATASOURCE_CONFIG d

    AND name LIKE CONCAT('%', #{name}, '%')
    AND db_type = #{dbType}
    AND status = #{status, typeHandler=com.gitee.apigrab.persistence.handler.EnableStatusTypeHandler}

ORDER BY id DESC

mapper.update:
UPDATE APIGRAB_DATASOURCE_CONFIG
name = #{name}, db_type = #{dbType}, db_version = #{dbVersion}, jdbc_url = #{jdbcUrl}, driver_class = #{driverClass}, driver_path = #{driverPath}, username = #{username}, password = #{password}, pool_max_size = #{poolMaxSize}, pool_min_idle = #{poolMinIdle}, conn_props = #{connProps, typeHandler=com.gitee.apigrab.persistence.handler.ObjectMapTypeHandler}, status = #{status, typeHandler=com.gitee.apigrab.persistence.handler.EnableStatusTypeHandler}, remark = #{remark},
WHERE id = #{id}
